const fs = require('fs');
const { execFileSync } = require('child_process');

const obj = [
  'v 0 0 0','v 1 0 0','v 1 1 0','v 0 1 0',
  'v 0 0 1','v 1 0 1','v 1 1 1','v 0 1 1',
  'f 1 4 3','f 1 2 3','f 5 6 7','f 5 8 7',
  'f 1 2 6','f 1 6 5','f 2 3 7','f 2 7 6',
  'f 3 4 8','f 3 7 8','f 4 1 5','f 4 5 8'
].join('\n') + '\n';

fs.writeFileSync('in.obj', obj);

const fix = `const fs = require('fs');
const lines = fs.readFileSync('in.obj', 'utf8').split(/\\r?\\n/).filter(l => l.trim() !== '');
const verts = [];
const vlines = [];
const faces = [];
for (const l of lines) {
  const t = l.trim().split(/\\s+/);
  if (t[0] === 'v') { verts.push([+t[1], +t[2], +t[3]]); vlines.push(l.trim()); }
  else if (t[0] === 'f') faces.push(t.slice(1).map(Number));
}
let cx = 0, cy = 0, cz = 0;
for (const v of verts) { cx += v[0]; cy += v[1]; cz += v[2]; }
cx /= verts.length; cy /= verts.length; cz /= verts.length;
const out = vlines.slice();
let inverted = 0;
for (const f of faces) {
  const a = verts[f[0]-1], b = verts[f[1]-1], c = verts[f[2]-1];
  const u = [b[0]-a[0], b[1]-a[1], b[2]-a[2]];
  const w = [c[0]-a[0], c[1]-a[1], c[2]-a[2]];
  const n = [u[1]*w[2]-u[2]*w[1], u[2]*w[0]-u[0]*w[2], u[0]*w[1]-u[1]*w[0]];
  const g = [(a[0]+b[0]+c[0])/3-cx, (a[1]+b[1]+c[1])/3-cy, (a[2]+b[2]+c[2])/3-cz];
  const d = n[0]*g[0] + n[1]*g[1] + n[2]*g[2];
  let ff = f;
  if (d < 0) { ff = [f[0], f[2], f[1]]; inverted++; }
  out.push('f ' + ff.join(' '));
}
fs.writeFileSync('fixed.obj', out.join('\\n') + '\\n');
console.log(JSON.stringify({ total: faces.length, inverted: inverted, fixed: inverted }));
`;

