const fs = require('fs/promises');
const { Worker, isMainThread, workerData, parentPort } = require('worker_threads');

const COUNTER = 'counter.json';
const LOG = 'log.txt';
const N = process.argv[2] === undefined ? 0 : Number(process.argv[2]);

// Single writer: every read-modify-write of counter.json and every append to
// log.txt goes through this serialized promise chain, so no two tasks can
// interleave inside the critical section (fixes the lost update).
let chain = Promise.resolve();
function enqueue(fn) {
  const p = chain.then(fn);
  chain = p.then(function () {}, function () {});
  return p;
}

// one atomic increment (read -> +1 -> write) plus this task's own log append
async function taskIncrement(id) {
  const cur = JSON.parse(await fs.readFile(COUNTER, 'utf8'));
  const next = cur.n + 1;
  await fs.writeFile(COUNTER, JSON.stringify({ n: next }));
  await fs.appendFile(LOG, 'task ' + id + ' increment -> n=' + next + '\\n');
  return next;
}

async function main() {
  // reset FIRST and awaited, before any task is started
  await fs.writeFile(COUNTER, JSON.stringify({ n: 0 }));
  await fs.writeFile(LOG, '');

  if (N > 0) {
    await new Promise(function (resolve, reject) {
      let finished = 0;
      for (let i = 0; i < N; i++) {
        const w = new Worker(__filename, { workerData: { id: i } });
        w.on('message', function (msg) {
          if (!msg || msg.type !== 'increment') return;
          enqueue(function () { return taskIncrement(msg.id); }).then(function () {
            finished += 1;
            if (finished === N) resolve();
          }, reject);
        });
        w.on('error', reject);
        w.on('exit', function (code) {
          if (code !== 0 && finished < N) reject(new Error('worker exited with code ' + code));
        });
      }
    });
  }

  const final = JSON.parse(await fs.readFile(COUNTER, 'utf8'));
  process.stdout.write('n=' + final.n + '\\n');
