'use strict';
const fs = require('fs');
const path = require('path');
const MOD = 1000000007;
const NL = String.fromCharCode(10);

const file = path.join(__dirname, 'data.txt');
const rs = fs.createReadStream(file, { encoding: 'utf8', highWaterMark: 1 << 16 });

let count = 0;
let sum = 0;
let mSign = 0;
let mLen = 0;
let mStr = '';

function consider(neg, data, s, e) {
  while (e - s > 1 && data.charCodeAt(s) === 48) s++;
  const len = e - s;
  let v = 0;
  for (let k = s; k < e; k++) v = (v * 10 + (data.charCodeAt(k) - 48)) % MOD;
  count++;
  sum = (sum + (neg ? (MOD - v) % MOD : v)) % MOD;
  const sign = neg ? -1 : 1;
  if (mLen === 0) { mSign = sign; mLen = len; mStr = data.slice(s, e); return; }
  if (sign > mSign) { mSign = sign; mLen = len; mStr = data.slice(s, e); return; }
  if (sign < mSign) return;
  let cmp = 0;
  if (len === mLen) {
    for (let k = 0; k < mLen; k++) {
      const d = data.charCodeAt(s + k) - mStr.charCodeAt(k);
      if (d !== 0) { cmp = d; break; }
    }
  } else cmp = len - mLen;
  if (sign > 0) { if (cmp > 0) { mLen = len; mStr = data.slice(s, e); } }
  else { if (cmp < 0) { mLen = len; mStr = data.slice(s, e); } }
}

function scan(data, from, to) {
  let i = from;
  while (i < to) {
    const c = data.charCodeAt(i);
    if (c >= 48 && c <= 57) {
      const s = i;
      while (i < to) { const d = data.charCodeAt(i); if (d >= 48 && d <= 57) i++; else break; }
      const neg = s > from && data.charCodeAt(s - 1) === 45;
      consider(neg, data, s, i);
    } else i++;
  }
}

let rem = '';
rs.on('data', function (chunk) {
  const data = rem.length ? rem + chunk : chunk;
  let start = 0;
  let idx;
  while ((idx = data.indexOf(NL, start)) !== -1) {
    scan(data, start, idx);
    start = idx + 1;
  }
  rem = data.slice(start);
});
rs.on('error', function (e) { process.stderr.write(String(e && e.message) + NL); process.exit(1); });
rs.on('end', function () {
  if (rem.length) scan(rem, 0, rem.length);
  let max = 0;
  if (mLen > 0) {
    const abs = mStr.length <= 15 ? Number(mStr) : Number(BigInt(mStr));
    max = mSign < 0 ? -abs : abs;
  }
  process.stdout.write(JSON.stringify({ count: count, sum: sum, max: max }) + NL);
});
`;
