'use strict';
const fs = require('fs');
const path = require('path');

const N = Number(process.argv[2]);
if (!Number.isInteger(N) || N < 0) {
  console.error('usage: node run.js N');
  process.exit(2);
}

const counterFile = path.join(__dirname, 'counter.json');
const logFile = path.join(__dirname, 'log.txt');

// 契约：启动时重置状态
fs.writeFileSync(counterFile, JSON.stringify({ n: 0 }));
fs.writeFileSync(logFile, '');

// 修复竞态：原文的任务并发执行 读-改-写，互相覆盖（丢更新）。
// 现在改为单写者串行队列：所有任务的读-改-写严格按提交顺序逐个完成。
let tail = Promise.resolve();
function enqueue(fn) {
  const run = tail.then(fn);
  tail = run.then(function () {}, function () {});
  return run;
}

function increment(i) {
  const cur = JSON.parse(fs.readFileSync(counterFile, 'utf8'));
  const next = { n: cur.n + 1 };
  fs.writeFileSync(counterFile, JSON.stringify(next));
  fs.appendFileSync(logFile, 'task ' + i + ' -> n=' + next.n + '\n');
}

const pending = [];
for (let i = 0; i < N; i++) {
  pending.push(enqueue(function () { return increment(i); }));
}

Promise.all(pending).then(function () {
  const finalN = JSON.parse(fs.readFileSync(counterFile, 'utf8')).n;
  process.stdout.write('n=' + finalN + '\n');
}).catch(function (err) {
  console.error(err);
  process.exit(1);
});

